-- All accounts, sessions, products and sales are synthetic and rolled back.
begin;
do $$
declare staff uuid:=gen_random_uuid(); outsider uuid:=gen_random_uuid(); sid uuid:=gen_random_uuid();
 product bigint; legacy_product bigint; rev bigint; op uuid:=gen_random_uuid(); result jsonb; first_sale bigint; last_sale bigint; hist jsonb;
begin
 insert into auth.users(id,email,email_confirmed_at) values(staff,'sales-probe-'||staff||'@example.invalid',now()),(outsider,'sales-probe-'||outsider||'@example.invalid',now());
 insert into auth.sessions(id,user_id,created_at,updated_at) values(sid,staff,now(),now());
 insert into public.store_admins(user_id,display_name,access_role) values(staff,'Sales probe employee','owner');
 perform set_config('request.jwt.claims',jsonb_build_object('sub',staff,'session_id',sid,'role','authenticated','aal','aal2')::text,true);
 set local role authenticated;
 insert into public.products(brand,name,category,currency,price,image_url,photos,available,size,stock_quantities,creation_key)
 values('Sales probe','Rollback fixture','Обувь','EUR',100,'https://juliproz-store.vercel.app/images/security-probe.webp','[]',true,'40; 41','{"40":2,"41":1}',gen_random_uuid()) returning id,revision into product,rev;
 begin update public.products set available=false,archive_status='sold' where id=product;raise exception 'FAIL forged sold status';exception when raise_exception then if sqlerrm='FAIL forged sold status' then raise;end if;end;
 begin perform public.store_record_product_sale(gen_random_uuid(),product,rev,current_date,1.5,'40',1);raise exception 'FAIL fractional amount';exception when raise_exception then if sqlerrm='FAIL fractional amount' then raise;end if;end;
 begin perform public.store_record_product_sale(gen_random_uuid(),product,rev,current_date,100,'40',3);raise exception 'FAIL oversell';exception when raise_exception then if sqlerrm='FAIL oversell' then raise;end if;end;
 result:=public.store_record_product_sale(op,product,rev,current_date,180,'40',2);first_sale:=(result->>'sale_id')::bigint;
 if (result->'product'->>'available')::boolean is not true or (result->'product'->'stock_quantities'->>'40')::integer<>0 or (result->'product'->'stock_quantities'->>'41')::integer<>1 then raise exception 'FAIL partial stock';end if;
 result:=public.store_record_product_sale(op,product,rev,current_date,180,'40',2);
 if result->>'already_recorded'<>'true' or (result->>'sale_id')::bigint<>first_sale then raise exception 'FAIL lost-response retry';end if;
 begin perform public.store_record_product_sale(op,product,rev,current_date,190,'40',2);raise exception 'FAIL reused operation with different amount';exception when raise_exception then if sqlerrm='FAIL reused operation with different amount' then raise;end if;end;
 begin perform public.store_record_product_sale(gen_random_uuid(),product,rev,current_date,100,'41',1);raise exception 'FAIL stale revision';exception when raise_exception then if sqlerrm='FAIL stale revision' then raise;end if;end;
 rev:=(result->'product'->>'revision')::bigint;
 result:=public.store_record_product_sale(gen_random_uuid(),product,rev,current_date,95,'41',1);last_sale:=(result->>'sale_id')::bigint;rev:=(result->'product'->>'revision')::bigint;
 if result->'product'->>'archive_status'<>'sold' or (result->'product'->>'available')::boolean is not false then raise exception 'FAIL final stock archive';end if;
 begin update public.products set available=true where id=product;raise exception 'FAIL direct sold restore';exception when raise_exception then if sqlerrm='FAIL direct sold restore' then raise;end if;end;
 begin perform public.store_void_product_sale(first_sale,rev,'Out of order');raise exception 'FAIL unsafe earlier cancellation';exception when raise_exception then if sqlerrm='FAIL unsafe earlier cancellation' then raise;end if;end;
 hist:=public.store_product_sales_history(null,product::text);
 if (hist->'summary'->>'count')::integer<>2 or (hist->'summary'->>'quantity')::integer<>3 or (hist->'summary'->>'amount')::numeric<>275 or hist->'rows'->0->>'actor_label'<>'Sales probe employee' then raise exception 'FAIL sales history totals or employee';end if;
 result:=public.store_void_product_sale(last_sale,rev,'Customer return');rev:=(result->'product'->>'revision')::bigint;
 if (result->'product'->>'available')::boolean is not true or (result->'product'->'stock_quantities'->>'41')::integer<>1 then raise exception 'FAIL return restores stock';end if;
 result:=public.store_void_product_sale(last_sale,rev,'Customer return');
 if result->>'already_voided'<>'true' then raise exception 'FAIL cancellation retry';end if;
 result:=public.store_void_product_sale(first_sale,rev,'Wrong sale entry');rev:=(result->'product'->>'revision')::bigint;
 if result->'product'->'stock_quantities'<>'{"40":2,"41":1}'::jsonb then raise exception 'FAIL partial return';end if;
 hist:=public.store_product_sales_history(null,product::text,null,null,'all');
 if (hist->'summary'->>'amount')::numeric<>0 or jsonb_array_length(hist->'rows')<>2 or hist->'rows'->0->>'void_reason'<>'Customer return' then raise exception 'FAIL cancellation history retained or excluded';end if;
 update public.products set available=false,archive_status='hidden',reserved=false where id=product returning revision into rev;
 if (public.store_product_sales_history(null,product::text)->'summary'->>'count')::integer<>0 then raise exception 'FAIL hiding counted as sale';end if;
 update public.products set available=true where id=product;
 if exists(select 1 from public.products where id=product and archive_status is not null) then raise exception 'FAIL hidden restore';end if;
 insert into public.products(brand,name,category,currency,image_url,photos,available,stock_quantities,creation_key)
 values('Sales probe','Legacy rollback fixture','Сумки','EUR','https://juliproz-store.vercel.app/images/security-probe.webp','[]',false,'{"":0}',gen_random_uuid()) returning id,revision into legacy_product,rev;
 if not exists(select 1 from public.products where id=legacy_product and archive_status='legacy') then raise exception 'FAIL legacy preserved';end if;
 result:=public.store_record_product_sale(gen_random_uuid(),legacy_product,rev,current_date-10,300,'',1);last_sale:=(result->>'sale_id')::bigint;
 if result->'product'->'stock_quantities'<>'{"":0}'::jsonb then raise exception 'FAIL legacy balance invented';end if;
 perform public.store_save_workspace_profile('Renamed probe');
 delete from public.products where id=legacy_product;
 hist:=public.store_product_sales_history(null,legacy_product::text);
 if jsonb_array_length(hist->'rows')<>1 or hist->'rows'->0->>'actor_label'<>'Sales probe employee' then raise exception 'FAIL deleted card or renamed employee lost snapshot';end if;
 perform public.store_void_product_sale(last_sale,null,'Deleted card correction');
 begin select count(*) into rev from store_private.product_sales;raise exception 'FAIL direct ledger read';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',staff,'session_id',sid,'role','authenticated','aal','aal1')::text,true);
 begin perform public.store_product_sales_history();raise exception 'FAIL MFA bypass';exception when insufficient_privilege then null;end;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',outsider,'session_id',sid,'role','authenticated','aal','aal2')::text,true);
 begin perform public.store_product_sales_history();raise exception 'FAIL outsider history';exception when insufficient_privilege then null;end;
 begin perform public.store_record_product_sale(gen_random_uuid(),product,rev,current_date,100,'40',1);raise exception 'FAIL outsider sale';exception when insufficient_privilege then null;end;
 reset role;
 delete from public.store_admins where user_id=staff;
 perform set_config('request.jwt.claims',jsonb_build_object('sub',staff,'session_id',sid,'role','authenticated','aal','aal2')::text,true);set local role authenticated;
 begin perform public.store_product_sales_history();raise exception 'FAIL revoked admin history';exception when insufficient_privilege then null;end;
 reset role;perform set_config('request.jwt.claims','{}',true);set local role anon;
 begin perform public.store_product_sales_history();raise exception 'FAIL anonymous history';exception when insufficient_privilege then null;end;
 begin select count(*) into rev from store_private.product_sales;raise exception 'FAIL anonymous ledger';exception when insufficient_privilege then null;end;
 reset role;
 if has_table_privilege('anon','store_private.product_sales','SELECT') or has_table_privilege('authenticated','store_private.product_sales','INSERT') then raise exception 'FAIL ledger grants';end if;
end $$;
select 'PASS: partial/final sales, stock bounds, revision conflicts, idempotent retries, hidden/legacy isolation, cancellation/retained snapshots, employee identity, MFA and anonymous/nonadmin/revoked denial; fixtures rolled back' as verification;
rollback;
